const anchorOnlyProps = new Set([
  "download",
  "href",
  "hrefLang",
  "media",
  "ping",
  "rel",
  "target",
  "type",
  "referrerPolicy",
]);

export const splitAnchorProps = (props: Record<string, unknown>) => {
  const anchorProps: Record<string, unknown> = {};
  const divProps: Record<string, unknown> = {};

  for (const key in props) {
    if (Object.prototype.hasOwnProperty.call(props, key)) {
      if (anchorOnlyProps.has(key)) {
        anchorProps[key] = props[key];
      } else {
        divProps[key] = props[key];
      }
    }
  }

  return [anchorProps, divProps];
};
